// Preserve quoted text/identifiers and line positions; discard nested SQL comments.
export function withoutSqlComments(sql) {
  let out = '', quote = null, depth = 0;
  for (let n = 0; n < sql.length; n++) {
    const c = sql[n], next = sql[n + 1];
