      else if (c === '*' && next === '/') { depth--; out += '  '; n++; }
      else out += c === '\n' ? '\n' : ' ';
    } else if (quote) {
      out += c;
      if (c === '\\' && quote === "'" && next) { out += next; n++; }
      else if (c === quote) { if (next === quote) { out += next; n++; } else quote = null; }
    } else if (c === "'" || c === '"') { quote = c; out += c; }
